const body = $('Webhook').item.json.body;
const brandItem = $('Lookup Brand Profile').all()[0];
const brand = brandItem ? brandItem.json : {};
const styleItem = $('Lookup Branch Style').all()[0];
const style = styleItem ? styleItem.json : {};
const primary = style.primary_color || '';
const secondary = style.secondary_color || '';
const accent = style.accent_color || '';
// Standing per-brand call to action (e.g. the Instagram 'link in bio' nudge).
// Appended to every caption so a batch of posts comes out publish-ready
// instead of needing the same line typed onto each one by hand.
const defaultCta = style.default_cta || '';

// Prefer the `branches` row (keyed by the exact slug the app sends, and
// populated for every branch) over `brand_profiles` (keyed by DOMAIN, so a
// slug like 'rejoice' never prefix-matched 'letsrejoice.app').
const brandName = style.name || brand.brand_name || body.branch || 'the brand';
const tone = body.tone || style.tone || brand.default_tone || 'friendly';
const pron = brand.pronunciation_guide || '';
const aspect = body.aspect_ratio || '1:1';
const setting = body.setting || brand.default_setting || 'a clean, bright, on-brand backdrop';
const platform = body.platform || 'general';
const styleNotes = body.style_notes || '';
const message = body.message || '';
const segment = body.target_segment || 'general audience';
const referenceImageUrl = body.reference_image_url || '';
const referenceMode = (body.reference_mode === 'edit') ? 'edit' : 'inspire';
const revisionNotes = body.revision_notes || '';

let copy_prompt = 'You are a senior direct-response copywriter and photo art director creating a single static social ad. Brand: ' + brandName + '. Tone: ' + tone + '. Audience: ' + segment + '. Platform: ' + platform + '. Core message: ' + message + '. Pronunciation and brand rules: ' + pron + '. ' + (styleNotes ? ('Style notes: ' + styleNotes + '. ') : '') + 'Write the finished ad content itself - never instructions, field descriptions or commentary.\n\nReturn:\nheadline_variants: exactly 5 headlines, each a MAXIMUM of 7 words, each using a DIFFERENT persuasion angle in this exact order - (1) direct benefit, (2) curiosity/intrigue, (3) urgency or scarcity, (4) belonging/social proof, (5) voice-of-customer phrasing as if a real customer said it. If the core message above specifies an exact tagline or exact wording, at least one of the 5 variants MUST use that wording VERBATIM.\nsubhead: one supporting line, max 12 words.\ncta: 2-4 words.\ncaption: a publish-ready social caption, 1-3 sentences, up to 3 hashtags.\nscene_brief: 1-2 sentences describing the ideal PHOTOGRAPH for this ad - the subject, action, setting, time of day and mood. Describe ONLY what the camera sees. Do not mention any text, graphics, headline or logo - those are added separately afterward, not by you.';
if (revisionNotes) {
  copy_prompt += ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes;
}

if (defaultCta) {
  copy_prompt += ' The caption MUST end with this exact call to action, word for word, as its final line: ' + defaultCta;
}

return [{ json: {
  copy_prompt,
  brand_name: brandName,
  tone,
  aspect_ratio: aspect,
  setting,
  platform,
  style_notes: styleNotes,
  message,
  job_id: body.job_id,
  branch: body.branch,
  reference_image_url: referenceImageUrl,
  reference_mode: referenceMode,
  revision_notes: revisionNotes,
  primary,
  secondary,
  accent,
  default_cta: defaultCta,
} }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const prep = $('Prepare Copy Prompt').item.json;
const revisionNotes = prep.revision_notes || '';
const primary = prep.primary || '';
const secondary = prep.secondary || '';
const accent = prep.accent || '';

function extractJson(text) {
  try { return JSON.parse(text); } catch (e) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return null;
}

let copy = extractJson(raw);

// A headline that is really schema/markdown junk is worse than no copy at
// all, because the app composites it onto the image afterward. Reject those outright.
const looksLikeJunk = (s) => !s
  || /`|\bmax \d+ words\b|\bcall to\b\s*$|^\s*[-*#]/i.test(s)
  || /^(headline|headline_variants|subhead|subtext|cta|caption|scene_brief)\b/i.test(s);

const variantsOk = copy && typeof copy === 'object' && Array.isArray(copy.headline_variants) && copy.headline_variants.length > 0 && !looksLikeJunk(copy.headline_variants[0]);

if (!variantsOk) {
  // Fall back to the user's own words - they are always safe to show.
  const source = (prep.message || '').trim();
  const firstSentence = (source.split(/[.!?\n]/)[0] || prep.brand_name).trim();
  copy = {
    headline_variants: [firstSentence.split(/\s+/).slice(0, 7).join(' ') || prep.brand_name],
    subhead: source.slice(0, 90),
    cta: 'Learn More',
    caption: source.slice(0, 280) || (prep.brand_name + ' - new today.'),
    scene_brief: '',
  };
}

const headline_variants = copy.headline_variants
  .map((v) => (v || '').toString().trim())
  .filter(Boolean)
  .slice(0, 5);
if (headline_variants.length === 0) { headline_variants.push(prep.brand_name); }

const headline = headline_variants[0];
const subhead = (copy.subhead || '').toString();
const cta = (copy.cta || 'Learn More').toString();
const caption = (copy.caption || headline).toString();
const scene_brief = (copy.scene_brief || '').toString();

const hasRef = !!(prep.reference_image_url);
const refMode = prep.reference_mode || 'inspire';

// Real brand hex colours from the branches table beat the generic brand-name
// phrasing whenever they exist - brand_profiles.brand_colors is always empty.
const colorParts = [
  primary ? ('primary ' + primary) : '',
  secondary ? ('secondary ' + secondary) : '',
  accent ? ('accent ' + accent) : '',
].filter(Boolean);
const colorPhrase = colorParts.length
  ? ('Brand colour palette to echo in wardrobe, props and colour grade: ' + colorParts.join(', ') + '. ')
  : ('Colour palette and visual style consistent with ' + prep.brand_name + '. ');

// Clean area reserved for the headline the app composites afterward - tall
// 9:16 crops leave less usable footer space than square/portrait crops.
const cleanArea = (prep.aspect_ratio === '9:16') ? 'lower quarter' : 'lower third';
const spaceRule = 'Reserve the ' + cleanArea + ' of the frame as a clean area: visually calm and uncluttered - low detail, soft even tone, gentle falloff - for headline text to be added afterward. Keep the main subject clear of that area. ';
const spaceRuleEdit = 'If needed, crop or extend the composition so the ' + cleanArea + ' has a clean area (low detail, soft even tone, gentle falloff) reserved for headline text to be added afterward. Keep the main subject clear of that area. ';

// The main quality lever: real photographic craft language, not generic
// 'professional marketing image' phrasing. Skipped in 'edit' mode, where we
// are retouching a real photo rather than implying a fresh shoot.
const craft = 'Editorial commercial photograph, shot on a full-frame camera with a 35mm lens at f/2.0, shallow depth of field, natural directional light, authentic unposed moment, true-to-life skin tones, high dynamic range, subtle film grain. ';
const styleOverride = prep.style_notes ? ('Style notes (these take priority over the photographic direction above if they conflict): ' + prep.style_notes + '. ') : '';

const negativeClause = 'CRITICAL: the image must contain NO text, NO words, NO letters, NO numbers, NO logos, NO watermarks, NO signage, NO captions of any kind, and must avoid common AI rendering flaws: distorted hands or faces, extra or missing fingers, oversaturated colour, plastic/waxy skin, obvious stock-photo staging, collage panels, borders or frames, UI elements. A completely clean, authentic photograph.';
const negativeClauseEdit = 'CRITICAL: do not ADD any text, words, letters, numbers, logos, watermarks, signage or captions to this photograph beyond what may already exist in it, and avoid introducing rendering artefacts (distorted hands or faces, extra fingers, oversaturated colour, plastic skin). Do not render the headline or any other text onto the image - the app composites the headline separately afterward.';

const scene = scene_brief || (prep.setting + (prep.message ? ('. ' + prep.message) : '.'));

let image_prompt;
if (hasRef && refMode === 'edit') {
  image_prompt = 'The attached image is a real photograph. Edit THIS EXACT photograph into a finished marketing static advertisement. Preserve the authentic scene, people, objects and lighting exactly as photographed - do not replace, redraw or regenerate the scene, and do not introduce new lens, aperture or lighting effects that would imply a re-shoot. ' + spaceRuleEdit + 'You may apply only a subtle, tasteful colour grade consistent with ' + prep.brand_name + (colorParts.length ? (' and its brand colours (' + colorParts.join(', ') + ')') : '') + '. Output ' + prep.aspect_ratio + ' aspect ratio, cropping minimally if needed. ' + styleOverride + negativeClauseEdit;
} else if (hasRef) {
  image_prompt = 'Scene: ' + scene + ' A reference photograph is attached - use it ONLY as guidance for setting, mood, lighting and composition; generate a NEW original image in the same spirit, ' + prep.aspect_ratio + ' aspect ratio. ' + craft + colorPhrase + spaceRule + styleOverride + negativeClause;
} else {
  image_prompt = 'Scene: ' + scene + ' ' + prep.aspect_ratio + ' aspect ratio composition. ' + craft + colorPhrase + spaceRule + styleOverride + negativeClause;
}

if (revisionNotes) {
  image_prompt += ' REVISION REQUEST - the previous attempt was rejected. Apply this feedback: ' + revisionNotes;
}

return [{ json: {
  headline,
  headline_variants,
  subhead,
  cta,
  caption,
  scene_brief,
  image_prompt,
  job_id: prep.job_id,
  branch: prep.branch,
  aspect_ratio: prep.aspect_ratio,
  reference_image_url: prep.reference_image_url || '',
  reference_mode: refMode,
  revision_notes: revisionNotes,
  primary,
  secondary,
  accent,
} }];

const attempt = $runIndex + 1;
const prep = $('Parse Copy').item.json;
const cleanArea = (prep.aspect_ratio === '9:16') ? 'lower quarter' : 'lower third';
const retrySuffix = (attempt > 1)
  ? (' Regenerate this image and fix BOTH known issues from the previous attempt: (1) absolutely NO text, letters, words, numbers, logos, watermarks, signage or captions anywhere in the frame, and (2) the ' + cleanArea + ' of the frame must be visually calm and uncluttered - low detail, soft even tone, gentle falloff - with the main subject kept clear of it, so headline text can be placed over it afterward.')
  : '';
return [{ json: {
  attempt,
  image_prompt: prep.image_prompt,
  job_id: prep.job_id,
  branch: prep.branch,
  aspect_ratio: prep.aspect_ratio,
  reference_image_url: prep.reference_image_url || '',
  reference_mode: prep.reference_mode || 'inspire',
  revision_notes: prep.revision_notes || '',
  primary: prep.primary || '',
  secondary: prep.secondary || '',
  accent: prep.accent || '',
  clean_area_label: cleanArea,
  retry_suffix: retrySuffix,
} }];

const cands = $json.candidates || [];
let b64 = null;
let mime = 'image/png';

for (const c of cands) {
  const parts = (c.content && c.content.parts) || [];
  for (const p of parts) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) {
      b64 = inline.data;
      mime = inline.mimeType || inline.mime_type || mime;
      break;
    }
  }
  if (b64) break;
}

if (!b64) {
  throw new Error('No image returned by Gemini. Raw: ' + JSON.stringify($json).slice(0, 400));
}

const jobId = $('Parse Copy').item.json.job_id;
const attempt = $('Track Frame Attempt').item.json.attempt;
const ext = mime.includes('jpeg') ? 'jpg' : 'png';
const rand = Math.random().toString(36).slice(2, 8);
const path = 'static-ads/' + jobId + '/ad-' + attempt + '-' + rand + '.' + ext;

return [{
  json: { storage_path: path, mime, attempt, base64: b64 },
  binary: {
    data: {
      data: b64,
      mimeType: mime,
      fileName: 'ad-' + attempt + '-' + rand + '.' + ext,
    },
  },
}];

const text = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '';
const passed = /^\s*yes/i.test(text);
return [{ json: { passed, reason: text.slice(0, 300) } }];

const prep = $('Track Frame Attempt').item.json;
const binary = $input.item.binary && $input.item.binary.data;
if (!binary) { throw new Error('Reference image fetch returned no binary data'); }
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = binary.mimeType && binary.mimeType.startsWith('image/') ? binary.mimeType : 'image/jpeg';
return [{ json: Object.assign({}, prep, { ref_base64: buf.toString('base64'), ref_mime: mime }) }];
